}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x733f8B3545a810214D2D27EEC8c60f93b561C050;
    address attacker = address(this);
    UltramanCoin target;

    // ─── Setup ───────────────────────────────────────────────
